import WidgetKit
import AppIntents
import SwiftUI
import UIKit

// MARK: - Shared data (written by the app, read here)

/// What the app tells the widget: today's next step and progress.
/// The app writes it to the App Group "group.<app bundle id>". Without the App Groups capability
/// (it needs a paid Apple Developer account) the widget can't see it and shows a calm greeting instead.
struct TerraWidgetData: Codable {
    var day: String
    var lang: String
    var name: String
    /// "Why I started", in the person's own words (optional)
    var why: String?
    var next: String
    var routine: String
    var done: Int
    var total: Int
    var streak: Int
    var grown: Int
    var rem: String
    var remTime: String
    /// Next step per time of day ("dawn", "day", "dusk", "night"), so the widget reflects the hour.
    var parts: [String: TerraWidgetPart]? = nil
    /// The next step's id (for the Done button) and the few steps after it.
    var nextId: String? = nil
    var list: [TerraStepItem]? = nil
}

struct TerraWidgetPart: Codable {
    var next: String
    var routine: String
    var id: String? = nil
    var list: [TerraStepItem]? = nil
}

struct TerraStepItem: Codable, Hashable {
    var id: String
    var text: String
    var routine: String
}

extension TerraWidgetData {
    /// The same data, with the next step swapped for the one that fits this time of day.
    func forTime(_ date: Date) -> TerraWidgetData {
        var x = self
        if let p = parts?["\(Tod(date))"] {
            x.next = p.next
            x.routine = p.routine
            if let id = p.id { x.nextId = id }
            if let l = p.list { x.list = l }
        }
        return x.applyingDone(TerraWidgetStore.doneQueue(day: x.day))
    }

    /// Steps ticked off in the widget disappear at once; the next one moves up.
    func applyingDone(_ q: Set<String>) -> TerraWidgetData {
        guard !q.isEmpty, let before = list else { return self }
        var x = self
        let rest = before.filter { !q.contains($0.id) }
        x.list = rest
        x.next = rest.first?.text ?? ""
        x.routine = rest.first?.routine ?? ""
        x.nextId = rest.first?.id
        x.done = min(x.total, x.done + (before.count - rest.count))
        return x
    }
}

/// Ticks a step off right from the widget (iOS 17+). Terra picks it up the next time it opens.
struct TerraDoneStepIntent: AppIntent {
    static let title: LocalizedStringResource = "Mark step done"
    static let isDiscoverable: Bool = false
    @Parameter(title: "Step") var stepId: String
    init() {}
    init(stepId: String) { self.stepId = stepId }
    func perform() async throws -> some IntentResult {
        TerraWidgetStore.markDone(stepId)
        return .result()
    }
}

enum TerraWidgetStore {
    static let key = "terra.widget"
    static var group: String {
        let id = Bundle.main.bundleIdentifier ?? "terra"
        let app = id.hasSuffix(".widget") ? String(id.dropLast(".widget".count)) : id
        return "group." + app
    }
    static func load() -> TerraWidgetData? {
        guard let json = UserDefaults(suiteName: group)?.string(forKey: key),
              let data = json.data(using: .utf8) else { return nil }
        return try? JSONDecoder().decode(TerraWidgetData.self, from: data)
    }
    static let doneKey = "terra.widget.done"
    static func doneQueue(day: String) -> Set<String> {
        let all = UserDefaults(suiteName: group)?.stringArray(forKey: doneKey) ?? []
        return Set(all.compactMap { e -> String? in
            let p = e.split(separator: "|", maxSplits: 1)
            return p.count == 2 && String(p[0]) == day ? String(p[1]) : nil
        })
    }
    static func markDone(_ id: String) {
        let defaults = UserDefaults(suiteName: group)
        var all = defaults?.stringArray(forKey: doneKey) ?? []
        let e = todayKey() + "|" + id
        if !all.contains(e) { all.append(e) }
        defaults?.set(all, forKey: doneKey)
    }
    static func todayKey(_ d: Date = Date()) -> String {
        let f = DateFormatter(); f.calendar = Calendar(identifier: .gregorian); f.dateFormat = "yyyy-MM-dd"; return f.string(from: d)
    }
}

// MARK: - Time of day (same hours as the app)

enum Tod {
    case dawn, day, dusk, night
    init(_ d: Date) {
        let h = Calendar.current.component(.hour, from: d)
        self = h >= 5 && h < 11 ? .dawn : h >= 11 && h < 17 ? .day : h >= 17 && h < 21 ? .dusk : .night
    }
    var sky: [Color] {
        switch self {
        case .dawn: return [Color(hex: 0xA98BD6), Color(hex: 0xF2A3A4), Color(hex: 0xFFD6AA)]
        case .day: return [Color(hex: 0x6FB9F0), Color(hex: 0xA9DCFB), Color(hex: 0xE2F4FF)]
        case .dusk: return [Color(hex: 0x56408F), Color(hex: 0xC26F93), Color(hex: 0xFFB27A)]
        case .night: return [Color(hex: 0x100C22), Color(hex: 0x1F1840), Color(hex: 0x35296B)]
        }
    }
    var hills: (Color, Color) {
        switch self {
        case .dawn: return (Color(hex: 0x8FD2A8), Color(hex: 0x4FAE86))
        case .day: return (Color(hex: 0x9BE0B6), Color(hex: 0x4FB68A))
        case .dusk: return (Color(hex: 0x6F9E8A), Color(hex: 0x3F6E63))
        case .night: return (Color(hex: 0x3D3266), Color(hex: 0x2A2150))
        }
    }
    /// Text on top of the scene stays readable: dark text on light skies, cream on dark ones.
    var ink: Color { self == .day || self == .dawn ? Color(hex: 0x241A3A) : Color(hex: 0xFFF3D6) }
    static func boundaries(after d: Date) -> [Date] {
        let cal = Calendar.current
        var out: [Date] = []
        for dayOffset in 0...1 {
            guard let base = cal.date(byAdding: .day, value: dayOffset, to: cal.startOfDay(for: d)) else { continue }
            for h in [0, 5, 8, 11, 14, 17, 19, 21, 22] { // sky changes, plus the hours when the cheer gets more urgent
                if let t = cal.date(byAdding: .hour, value: h, to: base), t > d { out.append(t) }
            }
        }
        return out
    }
}

extension Color {
    init(hex: UInt32) {
        self.init(red: Double((hex >> 16) & 0xFF) / 255, green: Double((hex >> 8) & 0xFF) / 255, blue: Double(hex & 0xFF) / 255)
    }
}

// MARK: - Words (English / Finnish, following the app's language)

struct Words {
    let fi: Bool
    init(_ data: TerraWidgetData?) {
        if let l = data?.lang { fi = l == "fi" } else { fi = Locale.current.language.languageCode?.identifier == "fi" }
    }
    func greet(_ tod: Tod) -> String {
        switch tod {
        case .dawn: return fi ? "Hyvää huomenta" : "Good morning"
        case .day: return fi ? "Hyvää päivää" : "Good afternoon"
        case .dusk: return fi ? "Hyvää iltaa" : "Good evening"
        case .night: return fi ? "Hyvää yötä" : "Good night"
        }
    }
    var nextLabel: String { fi ? "Seuraava askel" : "Next step" }
    var allDone: String { fi ? "Kaikki tehty tänään" : "All done for today" }
    var rest: String { fi ? "Lepokin on tärkeää." : "Rest counts too." }
    var newDay: String { fi ? "Uusi päivä. Avaa Terra ja aloita yhdellä askeleella." : "A new day. Open Terra for your first step." }
    var tagline: String { fi ? "Yksi pieni askel kerrallaan." : "One small step at a time." }
    var open: String { fi ? "Avaa Terra" : "Open Terra" }
    var upNext: String { fi ? "Seuraavaksi" : "Up next" }
    var qReminder: String { fi ? "Muistutus" : "Reminder" }
    var qRoutine: String { fi ? "Rutiini" : "Routine" }
    var qWorkout: String { fi ? "Treeni" : "Workout" }
    var qBreathe: String { fi ? "Hengitä" : "Breathe" }
    var done: String { fi ? "Tehty" : "Done" }
    func days(_ n: Int) -> String { fi ? "\(n) pv putki" : "\(n)-day streak" }
}

// MARK: - Timeline

struct TerraEntry: TimelineEntry {
    let date: Date
    let data: TerraWidgetData?
    var tod: Tod { Tod(date) }
    /// Data from yesterday doesn't count today.
    var today: TerraWidgetData? {
        guard let d = data, d.day == TerraWidgetStore.todayKey(date) else { return nil }
        return d
    }
    var isStale: Bool { data != nil && today == nil }
    /// Nothing to tick off right now (no data yet, or all done): the character keeps the widget company.
    var calm: Bool { today == nil || (today?.next.isEmpty ?? true) }
}

struct TerraProvider: TimelineProvider {
    func placeholder(in context: Context) -> TerraEntry {
        TerraEntry(date: Date(), data: .sample)
    }
    func getSnapshot(in context: Context, completion: @escaping (TerraEntry) -> Void) {
        completion(TerraEntry(date: Date(), data: context.isPreview ? .sample : TerraWidgetStore.load()?.forTime(Date())))
    }
    func getTimeline(in context: Context, completion: @escaping (Timeline<TerraEntry>) -> Void) {
        let now = Date()
        let data = TerraWidgetStore.load()
        // One entry now, then one at each change of the sky (and at midnight, when the day resets).
        let dates = [now] + Tod.boundaries(after: now)
        completion(Timeline(entries: dates.map { TerraEntry(date: $0, data: data?.forTime($0)) }, policy: .atEnd))
    }
}

extension TerraWidgetData {
    static let sample = TerraWidgetData(day: TerraWidgetStore.todayKey(), lang: "en", name: "Roni", next: "Drink a glass of water",
                                        routine: "Gentle morning", done: 3, total: 8, streak: 5, grown: 23, rem: "💊 Take vitamins", remTime: "09:00")
}

// MARK: - Terra's character (the same illustration as in the app), kept inline so the widget needs no extra assets

enum TerraArt {
    static let lean: UIImage? = UIImage(data: Data(base64Encoded: "") ?? Data())
    static let hug: UIImage? = UIImage(data: Data(base64Encoded: "") ?? Data())
    static func forTod(_ t: Tod) -> UIImage? { t == .night || t == .dusk ? hug : lean }
}

// MARK: - Scene (drawn like the app: sky, sun or moon, two hills)

struct Hill: Shape {
    let left: CGFloat, right: CGFloat, dip: CGFloat
    func path(in r: CGRect) -> Path {
        var p = Path()
        p.move(to: CGPoint(x: 0, y: r.height * left))
        p.addQuadCurve(to: CGPoint(x: r.width, y: r.height * right), control: CGPoint(x: r.width * 0.42, y: r.height * dip))
        p.addLine(to: CGPoint(x: r.width, y: r.height))
        p.addLine(to: CGPoint(x: 0, y: r.height))
        p.closeSubpath()
        return p
    }
}

struct SceneBackground: View {
    let tod: Tod
    var showChar = false
    var body: some View {
        GeometryReader { g in
            let s = min(g.size.width, g.size.height)
            ZStack {
                LinearGradient(colors: tod.sky, startPoint: .top, endPoint: .bottom)
                if tod == .night {
                    ForEach(0..<6, id: \.self) { i in
                        Circle().fill(Color(hex: 0xFFF4CF))
                            .frame(width: i % 2 == 0 ? 3 : 2, height: i % 2 == 0 ? 3 : 2)
                            .position(x: g.size.width * [0.12, 0.38, 0.55, 0.7, 0.86, 0.24][i], y: g.size.height * [0.12, 0.08, 0.2, 0.1, 0.24, 0.3][i])
                    }
                    Image(systemName: "moon.fill")
                        .font(.system(size: s * 0.2))
                        .foregroundStyle(Color(hex: 0xFFF1C4))
                        .position(x: g.size.width * 0.8, y: g.size.height * 0.5)
                } else {
                    Circle()
                        .fill(tod == .dusk ? Color(hex: 0xFF9A5C) : Color(hex: 0xFFD95E))
                        .frame(width: s * 0.3, height: s * 0.3)
                        .position(x: g.size.width * 0.8, y: g.size.height * 0.56) // rests on the hills, clear of the text
                }
                Hill(left: 0.66, right: 0.58, dip: 0.5).fill(tod.hills.0)
                Hill(left: 0.84, right: 0.76, dip: 0.7).fill(tod.hills.1)
                if showChar, let img = TerraArt.forTod(tod) {
                    Image(uiImage: img).resizable().scaledToFit()
                        .frame(height: g.size.height * 0.62)
                        .position(x: g.size.width * 0.8, y: g.size.height * 0.66)
                }
            }
        }
    }
}

// MARK: - Views

struct ProgressCapsule: View {
    let done: Int, total: Int, ink: Color
    var body: some View {
        GeometryReader { g in
            ZStack(alignment: .leading) {
                Capsule().fill(ink.opacity(0.18))
                Capsule().fill(Color(hex: 0xF5C35B))
                    .frame(width: total > 0 ? max(6, g.size.width * CGFloat(done) / CGFloat(total)) : 0)
            }
        }
        .frame(height: 6)
    }
}

struct SmallView: View {
    let entry: TerraEntry
    var body: some View {
        let w = Words(entry.data), tod = entry.tod, ink = tod.ink
        VStack(alignment: .leading, spacing: 4) {
            if let d = entry.today {
                if d.next.isEmpty {
                    Text(w.allDone).font(.system(size: 15, weight: .bold, design: .rounded))
                    CheerBubble(text: Cheer(entry.data, date: entry.date, stale: false).text, size: 11, lines: 3)
                } else {
                    VStack(alignment: .leading, spacing: 2) {
                        Text(w.nextLabel.uppercased()).font(.system(size: 9, weight: .bold, design: .rounded)).tracking(0.6).opacity(0.75)
                        Text(d.next).font(.system(size: 15, weight: .bold, design: .rounded)).lineLimit(3).minimumScaleFactor(0.8)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .glass(8)
                }
                Spacer(minLength: 0)
                HStack {
                    Text("\(d.done)/\(d.total)").font(.system(size: 12, weight: .bold, design: .rounded)).monospacedDigit()
                    Spacer()
                    if let id = d.nextId, !id.isEmpty, !d.next.isEmpty {
                        DoneButton(id: id, label: w.done, size: 30)
                    } else if d.streak > 1 {
                        Text("🔥 \(d.streak)").font(.system(size: 12, weight: .bold, design: .rounded))
                    }
                }
                ProgressCapsule(done: d.done, total: d.total, ink: ink)
            } else {
                Text(w.greet(tod)).font(.system(size: 16, weight: .bold, design: .rounded))
                Text(entry.isStale ? w.newDay : w.tagline).font(.system(size: 12, weight: .medium, design: .rounded)).opacity(0.9).lineLimit(3)
                    .frame(maxWidth: 110, alignment: .leading)
                Spacer(minLength: 0)
            }
        }
        .foregroundStyle(ink)
        .softShadow()
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
    }
}

struct MediumView: View {
    let entry: TerraEntry
    var body: some View {
        let w = Words(entry.data), tod = entry.tod, ink = tod.ink
        VStack(alignment: .leading, spacing: 6) {
            HStack(alignment: .firstTextBaseline) {
                CheerBubble(text: Cheer(entry.data, date: entry.date, stale: entry.isStale).text, size: 12, lines: 1)
                Spacer(minLength: 4)
                if let d = entry.today, d.streak > 0 { StreakFlame(streak: d.streak, size: 11) }
            }
            if let d = entry.today {
                if d.next.isEmpty {
                    Text(w.allDone).font(.system(size: 20, weight: .bold, design: .rounded))
                    Text(w.rest).font(.system(size: 13, weight: .medium, design: .rounded)).opacity(0.85)
                } else {
                    HStack(alignment: .center, spacing: 10) {
                        VStack(alignment: .leading, spacing: 2) {
                            Text(d.next).font(.system(size: 20, weight: .bold, design: .rounded)).lineLimit(2).minimumScaleFactor(0.8)
                            if !d.routine.isEmpty { Text(d.routine).font(.system(size: 12, weight: .medium, design: .rounded)).opacity(0.75).lineLimit(1) }
                        }
                        Spacer(minLength: 0)
                        if let id = d.nextId, !id.isEmpty { DoneButton(id: id, label: w.done, size: 42) }
                    }
                    .glass(9)
                }
                Spacer(minLength: 0)
                if !d.rem.isEmpty {
                    Text("\(d.remTime) · \(d.rem)").font(.system(size: 12, weight: .semibold, design: .rounded)).lineLimit(1).opacity(0.85)
                }
                HStack(spacing: 8) {
                    ProgressCapsule(done: d.done, total: d.total, ink: ink)
                    Text("\(d.done)/\(d.total)").font(.system(size: 12, weight: .bold, design: .rounded)).monospacedDigit()
                    QuickIcons(w: w, ink: ink)
                }
            } else {
                Text(entry.isStale ? w.newDay : w.tagline).font(.system(size: 18, weight: .bold, design: .rounded)).lineLimit(2)
                    .frame(maxWidth: 200, alignment: .leading)
                Spacer(minLength: 0)
                QuickIcons(w: w, ink: ink)
            }
        }
        .foregroundStyle(ink)
        .softShadow()
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
    }
}

/// A soft frosted card that lifts the main content off the scene.
struct Glass: ViewModifier {
    var pad: CGFloat = 10
    func body(content: Content) -> some View {
        content.padding(pad)
            .background(RoundedRectangle(cornerRadius: 16, style: .continuous).fill(Color.white.opacity(0.13)))
            .overlay(RoundedRectangle(cornerRadius: 16, style: .continuous).stroke(Color.white.opacity(0.22), lineWidth: 0.6))
    }
}
extension View {
    func glass(_ pad: CGFloat = 10) -> some View { modifier(Glass(pad: pad)) }
    /// Keeps light text readable over the brighter parts of the sky
    func softShadow() -> some View { shadow(color: .black.opacity(0.22), radius: 3, y: 1) }
}

/// Quick buttons: each opens Terra at the right place.
enum Quick: CaseIterable {
    case reminder, routine, workout, breathe
    var url: URL { URL(string: "terra://" + ["add-reminder", "new-routine", "log-workout", "breathe"][Quick.allCases.firstIndex(of: self)!])! }
    var icon: String { ["bell.badge", "plus", "figure.strengthtraining.traditional", "wind"][Quick.allCases.firstIndex(of: self)!] }
    func label(_ w: Words) -> String { [w.qReminder, w.qRoutine, w.qWorkout, w.qBreathe][Quick.allCases.firstIndex(of: self)!] }
}

/// Medium: four round icon buttons.
struct QuickIcons: View {
    let w: Words, ink: Color
    var body: some View {
        HStack(spacing: 6) {
            ForEach(Quick.allCases, id: \.self) { q in
                Link(destination: q.url) {
                    Image(systemName: q.icon).font(.system(size: 12, weight: .bold))
                        .frame(width: 28, height: 28)
                        .background(Circle().fill(ink.opacity(0.16)))
                }
                .accessibilityLabel(q.label(w))
            }
        }
    }
}

/// Large: labelled buttons in one row.
struct QuickRow: View {
    let w: Words, ink: Color
    var body: some View {
        HStack(spacing: 6) {
            ForEach(Quick.allCases, id: \.self) { q in
                Link(destination: q.url) {
                    VStack(spacing: 3) {
                        Image(systemName: q.icon).font(.system(size: 14, weight: .bold))
                        Text(q.label(w)).font(.system(size: 10, weight: .semibold, design: .rounded)).lineLimit(1).minimumScaleFactor(0.8)
                    }
                    .frame(maxWidth: .infinity).padding(.vertical, 7)
                    .background(RoundedRectangle(cornerRadius: 12, style: .continuous).fill(ink.opacity(0.14)))
                }
            }
        }
    }
}

/// A round gold check that ticks the step off without opening Terra.
struct DoneButton: View {
    let id: String
    let label: String
    var size: CGFloat = 34
    var body: some View {
        Button(intent: TerraDoneStepIntent(stepId: id)) {
            Image(systemName: "checkmark")
                .font(.system(size: size * 0.42, weight: .heavy))
                .foregroundStyle(Color(hex: 0x1A1426))
                .frame(width: size, height: size)
                .background(Circle().fill(Color(hex: 0xF5C35B)))
        }
        .buttonStyle(.plain)
        .accessibilityLabel(label)
    }
}

/// Large: the next few steps as a checklist you can tick off from the home screen.
struct LargeView: View {
    let entry: TerraEntry
    var body: some View {
        let w = Words(entry.data), tod = entry.tod, ink = tod.ink
        VStack(alignment: .leading, spacing: 10) {
            HStack(alignment: .firstTextBaseline) {
                let name = entry.data?.name ?? ""
                Text(name.isEmpty ? w.greet(tod) : "\(w.greet(tod)), \(name)")
                    .font(.system(size: 15, weight: .bold, design: .rounded)).lineLimit(1)
                Spacer()
                if let d = entry.today, d.streak > 0 { StreakFlame(streak: d.streak, size: 12) }
                if let d = entry.today {
                    Text("\(d.done)/\(d.total)").font(.system(size: 13, weight: .bold, design: .rounded)).monospacedDigit()
                }
            }
            CheerBubble(text: Cheer(entry.data, date: entry.date, stale: entry.isStale).text, size: 13, lines: 2)
            if let d = entry.today {
                let fallback: [TerraStepItem] = (d.nextId ?? "").isEmpty || d.next.isEmpty ? [] : [TerraStepItem(id: d.nextId ?? "", text: d.next, routine: d.routine)]
                let items = Array((d.list ?? fallback).prefix(4))
                if items.isEmpty {
                    Text(w.allDone).font(.system(size: 22, weight: .bold, design: .rounded))
                    Text(w.rest).font(.system(size: 13, weight: .medium, design: .rounded)).opacity(0.85)
                } else {
                    Text(w.upNext.uppercased()).font(.system(size: 10, weight: .bold, design: .rounded)).tracking(0.6).opacity(0.75)
                    ForEach(items, id: \.id) { it in
                        HStack(spacing: 10) {
                            Button(intent: TerraDoneStepIntent(stepId: it.id)) {
                                Image(systemName: "circle").font(.system(size: 22, weight: .semibold))
                            }
                            .buttonStyle(.plain)
                            .accessibilityLabel("\(w.done): \(it.text)")
                            VStack(alignment: .leading, spacing: 0) {
                                Text(it.text).font(.system(size: 15, weight: .semibold, design: .rounded)).lineLimit(1)
                                if !it.routine.isEmpty {
                                    Text(it.routine).font(.system(size: 11, weight: .medium, design: .rounded)).opacity(0.7).lineLimit(1)
                                }
                            }
                            Spacer(minLength: 0)
                        }
                        .glass(8)
                    }
                }
                Spacer(minLength: 0)
                if !d.rem.isEmpty {
                    Text("\(d.remTime) · \(d.rem)").font(.system(size: 12, weight: .semibold, design: .rounded)).lineLimit(1).opacity(0.85)
                }
                ProgressCapsule(done: d.done, total: d.total, ink: ink)
                QuickRow(w: w, ink: ink)
            } else {
                Text(entry.isStale ? w.newDay : w.tagline).font(.system(size: 20, weight: .bold, design: .rounded)).lineLimit(3)
                    .frame(maxWidth: 220, alignment: .leading)
                Spacer(minLength: 0)
                QuickRow(w: w, ink: ink)
            }
        }
        .foregroundStyle(ink)
        .softShadow()
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
    }
}

/// Lock screen (and StandBy): system-tinted, so no scene, just text and a ring.
struct RectangularView: View {
    let entry: TerraEntry
    var body: some View {
        let w = Words(entry.data)
        VStack(alignment: .leading, spacing: 1) {
            if let d = entry.today {
                HStack(spacing: 4) {
                    Image(systemName: entry.tod.symbol).font(.system(size: 11, weight: .bold))
                    Text("Terra").font(.system(size: 12, weight: .semibold, design: .rounded))
                    Spacer(minLength: 0)
                    Text("\(d.done)/\(d.total)").font(.system(size: 12, weight: .bold, design: .rounded)).monospacedDigit()
                }
                .widgetAccentable()
                Text(d.next.isEmpty ? w.allDone : d.next).font(.system(size: 15, weight: .bold, design: .rounded)).lineLimit(1).minimumScaleFactor(0.8)
                ProgressView(value: Double(d.done), total: Double(max(d.total, 1))).progressViewStyle(.linear).tint(.primary)
            } else {
                Text("Terra").font(.system(size: 12, weight: .semibold, design: .rounded)).widgetAccentable()
                Text(entry.isStale ? w.newDay : w.tagline).font(.system(size: 14, weight: .semibold, design: .rounded)).lineLimit(2)
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }
}

struct CircularView: View {
    let entry: TerraEntry
    var body: some View {
        if let d = entry.today, d.total > 0 {
            Gauge(value: Double(d.done), in: 0...Double(d.total)) {
                Image(systemName: "leaf.fill")
            } currentValueLabel: {
                Text("\(d.done)").font(.system(size: 15, weight: .bold, design: .rounded))
            }
            .gaugeStyle(.accessoryCircular)
        } else {
            ZStack {
                AccessoryWidgetBackground()
                Image(systemName: entry.tod.symbol).font(.system(size: 20, weight: .semibold))
            }
        }
    }
}

struct InlineView: View {
    let entry: TerraEntry
    var body: some View {
        let w = Words(entry.data)
        if let d = entry.today, !d.next.isEmpty {
            Text("\(Image(systemName: "leaf.fill")) \(d.next)")
        } else if entry.today != nil {
            Text("\(Image(systemName: "checkmark")) \(w.allDone)")
        } else {
            Text("\(Image(systemName: "sun.max.fill")) \(w.tagline)")
        }
    }
}

struct TerraWidgetView: View {
    @Environment(\.widgetFamily) var family
    let entry: TerraEntry
    var body: some View {
        switch family {
        case .accessoryRectangular:
            RectangularView(entry: entry).containerBackground(for: .widget) { Color.clear }
        case .accessoryCircular:
            CircularView(entry: entry).containerBackground(for: .widget) { Color.clear }
        case .accessoryInline:
            InlineView(entry: entry).containerBackground(for: .widget) { Color.clear }
        case .systemLarge:
            LargeView(entry: entry).containerBackground(for: .widget) { SceneBackground(tod: entry.tod, showChar: entry.calm) }
        case .systemMedium:
            MediumView(entry: entry).containerBackground(for: .widget) { SceneBackground(tod: entry.tod, showChar: entry.calm) }
        default:
            SmallView(entry: entry).containerBackground(for: .widget) { SceneBackground(tod: entry.tod, showChar: entry.calm) }
        }
    }
}

// MARK: - Widget

struct TerraWidget: Widget {
    var body: some WidgetConfiguration {
        StaticConfiguration(kind: "TerraToday", provider: TerraProvider()) { entry in
            TerraWidgetView(entry: entry)
        }
        .configurationDisplayName("Terra")
        .description("Tick off your next tiny step right from the home screen.")
        .supportedFamilies([.systemSmall, .systemMedium, .systemLarge, .accessoryRectangular, .accessoryCircular, .accessoryInline])
    }
}

@main
struct TerraWidgets: WidgetBundle {
    var body: some Widget {
        TerraWidget()
        TerraCheerWidget()
        TerraLiveWidget()
    }
}

extension Tod {
    /// Sun, sunset or moon for the lock screen, matching the time of day
    var symbol: String { switch self { case .dawn: return "sunrise.fill"; case .day: return "sun.max.fill"; case .dusk: return "sunset.fill"; case .night: return "moon.stars.fill" } }
}
